CREATE   proc AcquisitionDocumentFiles_Add @Document_Id uniqueidentifier, @FileName varchar(255), @FileContent varbinary(max) as

insert into AcquisitionDocumentFiles(Document_Id, FileName, FileContent)
values (@Document_Id, @FileName, @FileContent)

select 'success' as SQLResultType,'Acquisition document file added succesfully!' as message
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc AcquisitionDocumentFiles_GetByDocument @Document_Id uniqueidentifier as

select	a.Document_Id,
        a.FileName,
        a.FileContent
from	AcquisitionDocumentFiles a
where	a.Document_Id = @Document_Id

GO
