GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc AcquisitionDocuments_Add	@Id uniqueidentifier, @Acquisition_Id uniqueidentifier, @DocumentType_Id uniqueidentifier, @Status int,
											@Issue_Date datetime, @Observation varchar(max), @User_Id uniqueidentifier, @Uploaded_Date datetime, @DVH char(64) as

insert into AcquisitionDocuments(Id, Acquisition_Id, DocumentType_Id, Status, Issue_Date, Observation, User_Id, Uploaded_Date, DVH)
values (@Id, @Acquisition_Id, @DocumentType_Id, @Status, @Issue_Date, @Observation, @User_Id, @Uploaded_Date, @DVH)

select 'success' as SQLResultType,'Acquisition document added succesfully!' as message
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc AcquisitionDocuments_Delete @Id uniqueidentifier as

-- El archivo escaneado se borra en cascada (AcquisitionDocumentFiles).
delete from AcquisitionDocuments
where Id = @Id

select 'success' as SQLResultType,'Acquisition document deleted succesfully!' as message
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc AcquisitionDocuments_GetByAcquisition @Acquisition_Id uniqueidentifier as

-- Documentos cargados de las dos etapas. Un tipo sin fila es un documento Pendiente.
select	a.Id,
        a.Acquisition_Id,
        a.DocumentType_Id,
        a.Status,
        a.Issue_Date,
        a.Observation,
        a.User_Id,
        a.Uploaded_Date,
        b.Description,
        b.Stage,
        c.FileName
from	AcquisitionDocuments a
        join AcquisitionDocumentTypes b on (b.Id = a.DocumentType_Id)
        left join AcquisitionDocumentFiles c on (c.Document_Id = a.Id)
where	a.Acquisition_Id = @Acquisition_Id
order by b.Display_Order asc

GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc AcquisitionDocuments_Observe	@Id uniqueidentifier, @Acquisition_Id uniqueidentifier, @DocumentType_Id uniqueidentifier, @Status int,
												@Issue_Date datetime, @Observation varchar(max), @User_Id uniqueidentifier, @Uploaded_Date datetime, @DVH char(64) as

-- CUF10 11.1: fila completa, el DVH se recalcula con todas las columnas aunque solo cambien estado y comentario.
update AcquisitionDocuments
set DVH = @DVH,
	Acquisition_Id = @Acquisition_Id,
	DocumentType_Id = @DocumentType_Id,
	Status = @Status,
	Issue_Date = @Issue_Date,
	Observation = @Observation,
	User_Id = @User_Id,
	Uploaded_Date = @Uploaded_Date
where Id = @Id

select 'success' as SQLResultType,'Acquisition document observed succesfully!' as message
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc AcquisitionDocumentTypes_GetByStage @Stage int as

-- Documentos obligatorios de cada etapa de CUF10: 1 Documentar, 2 Transferir.
select	a.Id,
        a.Description,
        a.Stage,
        a.Validity_Days,
        a.Display_Order
from	AcquisitionDocumentTypes a
where	a.Stage = @Stage
order by a.Display_Order asc

